    21	
    22	/**
    23	 * Writes wiki's JSON example in a streaming fashion using JsonGenerator
    24	 *
    25	 * @author Jitendra Kotamraju
    26	 */
    27	@Path("/generator")
    28	public class GeneratorResource {
    29	
    30	    @GET
    31	    @Produces(MediaType.APPLICATION_JSON)
    32	    public StreamingOutput doGet() {
    33	        return new StreamingOutput() {
    34	            public void write(OutputStream os) {
    35	                writeWikiExample(os);
    36	            }
    37	        };
    38	    }
    39	
    40	    // Writes wiki example JSON in a streaming fashion
    41	    private void writeWikiExample(OutputStream os) {
    42	        try(JsonGenerator gene = Json.createGenerator(os)) {
    43	            gene.writeStartObject()
    44	                .write("firstName", "John")
    45	                .write("lastName", "Smith")
    46	                .write("age", 25)
    47	                .writeStartObject("address")
    48	                    .write("streetAddress", "21 2nd Street")
    49	                    .write("city", "New York")
    50	                    .write("state", "NY")
    51	                    .write("postalCode", "10021")
    52	                .writeEnd()
    53	                .writeStartArray("phoneNumber")
    54	                    .writeStartObject()
    55	                        .write("type", "home")
    56	                        .write("number", "212 555-1234")
    57	                    .writeEnd()
    58	                    .writeStartObject()
    59	                        .write("type", "fax")
    60	                        .write("number", "646 555-4567")
    61	                    .writeEnd()
    62	                .writeEnd()
    63	            .writeEnd();
