    11	package org.eclipse.parsson.demos.facebook;
    12	
    13	import jakarta.json.*;
    14	import java.io.*;
    15	import java.net.HttpURLConnection;
    16	import java.net.URL;
    17	import java.util.Properties;
    18	
    19	/**
    20	 * Parses JSON from facebook graph API using object model API.
    21	 * JSON would like :
    22	 *
    23	 * {
    24	 *   data: [
    25	 *     { "from" : { "name" : "xxx", ... }, "message: "yyy", ... },
    26	 *     { "from" : { "name" : "ppp", ... }, "message: "qqq", ... },
    27	 *      ...
    28	 *   ],
    29	 *   ...
    30	 * }
    31	 *
    32	 * This codes writes the facebook posts to output as follows:
    33	 * xxx: yyy
    34	 * --------
    35	 * ppp: qqq
    36	 * --------
    37	 *
    38	 * @author Jitendra Kotamraju
    39	 */
    40	public class FacebookObjectSearch {
    41	
    42	    public static void main(String... args) throws Exception {
    43	        try (InputStream is = getSearchStream();
    44	             JsonReader rdr = Json.createReader(is)) {
    45	
    46	            JsonObject obj = rdr.readObject();
    47	            JsonArray results = obj.getJsonArray("data");
    48	            for (JsonObject result : results.getValuesAs(JsonObject.class)) {
    49	                JsonValue value = result.get("from");
    50	                if (value != null && value instanceof JsonObject) {
    51	                    System.out.print(((JsonObject)value).getString("name", "anon"));
    52	                }
    53	                System.out.print(": ");
    54	                System.out.println(result.getString("message", ""));
    55	                System.out.println("-----------");
    56	            }
    57	        }
    58	    }
    59	
    60	    static InputStream getSearchStream() throws Exception {
    61	        Properties config = new Properties();
    62	        config.load(FacebookObjectSearch.class.getResourceAsStream(
    63	                "/facebookconfig.properties"));
    64	        final String accessToken = (String)config.get("access_token");
    65	
    66	        // Gets the search stream
    67	        String searchUrl = "https://graph.facebook.com/search?q=tamil&type=post&access_token=";
    68	        URL url = new URL(searchUrl+accessToken);
    69	        HttpURLConnection con = (HttpURLConnection)url.openConnection();
    70	        return con.getInputStream();
    71	    }
    72	
    73	}
