    23	/**
    24	 * JsonPointer (http://tools.ietf.org/html/rfc6901) demo with object model API
    25	 *
    26	 * @author Jitendra Kotamraju
    27	 */
    28	public class JsonpointerDemo {
    29	
    30	    public static void main(String... args) throws Exception {
    31	        testWiki();
    32	        testPointer();
    33	        System.out.println("Both tests PASSED !!!");
    34	    }
    35	
    36	    private static void testWiki() throws IOException {
    37	        try (InputStream is = JsonpointerDemo.class.getResourceAsStream("/wiki.json");
    38	             JsonReader rdr = Json.createReader(is)) {
    39	            JsonObject person = rdr.readObject();
    40	
    41	            assertEquals("NY", getString(person, "/address/state"));
    42	            assertEquals("212 555-1234", getString(person, "/phoneNumber/0/number"));
    43	        }
    44	    }
    45	
    46	    private static void testPointer() throws IOException {
    47	        try (InputStream is = JsonpointerDemo.class.getResourceAsStream("/jsonpointer.json");
    48	             JsonReader rdr = Json.createReader(is)) {
    49	            JsonObject root = rdr.readObject();
    50	
    51	            assertEquals(root, get(root, ""));
    52	            assertEquals(root.get("foo"), get(root, "/foo"));
    53	            assertEquals(root.getJsonArray("foo").get(0), get(root, "/foo/0"));
    54	            assertEquals(root.get(""), get(root, "/"));
    55	            assertEquals(root.get("a/b"), get(root, "/a~1b"));
    56	            assertEquals(root.get("c%d"), get(root, "/c%d"));
    57	            assertEquals(root.get("e^f"), get(root, "/e^f"));
    58	            assertEquals(root.get("k\"l"), get(root, "/k\"l"));
    59	            assertEquals(root.get("i\\j"), get(root, "/i\\j"));
    60	            assertEquals(root.get(" "), get(root, "/ "));
    61	            assertEquals(root.get("m~n"), get(root, "/m~0n"));
    62	
    63	            // Adding a parent to current root and try with it
    64	            JsonObject doc = Json.createObjectBuilder().add("doc", root).build();
    65	            root = doc.getJsonObject("doc");
    66	            assertEquals(doc, get(doc, ""));
    67	            assertEquals(root.get("foo"), get(doc, "/doc/foo"));
    68	            assertEquals(root.getJsonArray("foo").get(0), get(doc, "/doc/foo/0"));
    69	            assertEquals(root.get(""), get(doc, "/doc/"));
    70	            assertEquals(root.get("a/b"), get(doc, "/doc/a~1b"));
    71	            assertEquals(root.get("c%d"), get(doc, "/doc/c%d"));
    72	            assertEquals(root.get("e^f"), get(doc, "/doc/e^f"));
    73	            assertEquals(root.get("k\"l"), get(doc, "/doc/k\"l"));
    74	            assertEquals(root.get("i\\j"), get(doc, "/doc/i\\j"));
    75	            assertEquals(root.get(" "), get(doc, "/doc/ "));
    76	            assertEquals(root.get("m~n"), get(doc, "/doc/m~0n"));
    77	        }
    78	    }
