    80	    private static String getString(JsonValue root, String pointer) {
    81	        return ((JsonString)get(root, pointer)).getString();
    82	    }
    83	
    84	    private static JsonValue get(JsonValue root, String pointer) {
    85	        if (pointer.isEmpty()) {
    86	            return root;
    87	        }
    88	        if (pointer.charAt(0) != '/') {
    89	            throw new IllegalArgumentException(
    90	                    "JsonPointer "+pointer+" doesn't start with /");
    91	        }
    92	
    93	        StringBuilder referenceToken = new StringBuilder();
    94	        for(int i=1; i < pointer.length(); i++) {   // 1 to skip first /
    95	            char ch = pointer.charAt(i);
    96	            if (ch == '/') {
    97	                return get(newRoot(root, referenceToken.toString()), pointer.substring(i));
    98	            } else if (ch == '~') {
    99	                // handle escaping ~0, ~1
   100	                if (i+1 == pointer.length()) {
   101	                    throw new IllegalArgumentException("Illegal escaping: expected ~0 or ~1, but got only ~ in pointer="+pointer);
   102	                }
   103	                ch = pointer.charAt(++i);
   104	                if (ch == '0') {
   105	                    referenceToken.append('~');
   106	                } else if (ch == '1') {
   107	                    referenceToken.append('/');
   108	                } else {
   109	                    throw new IllegalArgumentException("Illegal escaping: expected ~0 or ~1, but got ~"+ch+" in pointer="+pointer);
   110	                }
   111	            } else {
   112	                referenceToken.append(ch);
   113	            }
   114	        }
   115	        return newRoot(root, referenceToken.toString());
   116	    }
   117	
   118	    private static JsonValue newRoot(JsonValue root, String referenceToken) {
   119	        if (root instanceof JsonObject) {
   120	            return ((JsonObject)root).get(referenceToken);
   121	        } else if (root instanceof JsonArray) {
   122	            return ((JsonArray)root).get(Integer.parseInt(referenceToken));
   123	        }
   124	        throw new IllegalArgumentException("Illegal reference token="+referenceToken+" for value="+root);
   125	    }
   126	
   127	    private static void assertEquals(JsonValue exp, JsonValue got) {
   128	        if (exp != got) {
   129	            throw new RuntimeException("Expected = "+exp+" but got = "+got);
   130	        }
   131	    }
   132	
   133	    private static void assertEquals(String exp, String got) {
   134	        if (!exp.equals(got)) {
   135	            throw new RuntimeException("Expected = "+exp+" but got = "+got);
   136	        }
   137	    }
   138	
   139	}

