 94	        SQUAREOPEN(Event.START_ARRAY, false),
 95	        COLON(null, false),
 96	        COMMA(null, false),
 97	        STRING(Event.VALUE_STRING, true),
 98	        NUMBER(Event.VALUE_NUMBER, true),
 99	        TRUE(Event.VALUE_TRUE, true),
100	        FALSE(Event.VALUE_FALSE, true),
101	        NULL(Event.VALUE_NULL, true),
102	        CURLYCLOSE(Event.END_OBJECT, false),
103	        SQUARECLOSE(Event.END_ARRAY, false),
104	        EOF(null, false);
105	
106	        private final JsonParser.Event event;
107	        private final boolean value;
