129	    private void readString() {
130	        // when inPlace is true, no need to copy chars
131	        boolean inPlace = true;
132	        storeBegin = storeEnd = readBegin;
133	
134	        do {
135	            // Write unescaped char block within the current buffer
136	            if (inPlace) {
137	                int ch;
138	                while(readBegin < readEnd && ((ch=buf[readBegin]) >= 0x20) && ch != '\\') {
139	                    if (ch == '"') {
140	                        storeEnd = readBegin++; // ++ to consume quote char
141	                        return;                 // Got the entire string
142	                    }
143	                    readBegin++;                // consume unescaped char
144	                }
145	                storeEnd = readBegin;
146	            }
147	
148	            // string may be crossing buffer boundaries and may contain
149	            // escaped characters.
150	            int ch = read();
151	            if (ch >= 0x20 && ch != 0x22 && ch != 0x5c) {
152	                if (!inPlace) {
153	                    buf[storeEnd] = (char)ch;
154	                }
155	                storeEnd++;
156	                continue;
157	            }
158	            switch (ch) {
159	                case '\\':
160	                    inPlace = false;        // Now onwards need to copy chars
161	                    unescape();
162	                    break;
163	                case '"':
164	                    return;
165	                default:
166	                    throw unexpectedChar(ch);
167	            }
168	        } while (true);
169	    }
170	
171	    private void unescape() {
172	        int ch = read();
173	        switch (ch) {
174	            case 'b':
175	                buf[storeEnd++] = '\b';
176	                break;
177	            case 't':
178	                buf[storeEnd++] = '\t';
179	                break;
180	            case 'n':
181	                buf[storeEnd++] = '\n';
182	                break;
183	            case 'f':
184	                buf[storeEnd++] = '\f';
185	                break;
186	            case 'r':
187	                buf[storeEnd++] = '\r';
188	                break;
189	            case '"':
190	            case '\\':
191	            case '/':
192	                buf[storeEnd++] = (char)ch;
193	                break;
194	            case 'u': {
195	                int unicode = 0;
196	                for (int i = 0; i < 4; i++) {
197	                    int ch3 = read();
198	                    int digit = (ch3 >= 0 && ch3 < HEX_LENGTH) ? HEX[ch3] : -1;
199	                    if (digit < 0) {
200	                        throw unexpectedChar(ch3);
201	                    }
202	                    unicode = (unicode << 4)|digit;
203	                }
204	                buf[storeEnd++] = (char)unicode;
205	                break;
206	            }
207	            default:
208	                throw unexpectedChar(ch);
209	        }
210	    }
211	
212	    // Reads a number char. If the char is within the buffer, directly
213	    // reads from the buffer. Otherwise, uses read() which takes care
214	    // of resizing, filling up the buf, adjusting the pointers
215	    private int readNumberChar() {
216	        if (readBegin < readEnd) {
217	            return buf[readBegin++];
218	        } else {
219	            storeEnd = readBegin;
220	            return read();
221	        }
222	    }
223	
224	    private void readNumber(int ch)  {
225	        storeBegin = storeEnd = readBegin-1;
226	        // sign
227	        if (ch == '-') {
228	            this.minus = true;
229	            ch = readNumberChar();
230	            if (ch < '0' || ch >'9') {
231	                throw unexpectedChar(ch);
232	            }
233	        }
234	
235	        // int
236	        if (ch == '0') {
237	            ch = readNumberChar();
238	        } else {
239	            do {
240	                ch = readNumberChar();
241	            } while (ch >= '0' && ch <= '9');
242	        }
243	
244	        // frac
245	        if (ch == '.') {
246	            this.fracOrExp = true;
247	            int count = 0;
248	            do {
249	                ch = readNumberChar();
250	                count++;
251	            } while (ch >= '0' && ch <= '9');
252	            if (count == 1) {
253	                throw unexpectedChar(ch);
254	            }
255	        }
256	
257	        // exp
258	        if (ch == 'e' || ch == 'E') {
259	            this.fracOrExp = true;
260	            ch = readNumberChar();
261	            if (ch == '+' || ch == '-') {
262	                ch = readNumberChar();
263	            }
264	            int count;
265	            for (count = 0; ch >= '0' && ch <= '9'; count++) {
266	                ch = readNumberChar();
267	            }
268	            if (count == 0) {
269	                throw unexpectedChar(ch);
270	            }
271	        }
272	        if (ch != -1) {
273	            // Only reset readBegin if eof has not been reached
274	            readBegin--;
275	            storeEnd = readBegin;
276	        }
277	    }
278	
279	    private void readTrue() {
280	        int ch1 = read();
281	        if (ch1 != 'r') {
282	            throw expectedChar(ch1, 'r');
283	        }
284	        int ch2 = read();
285	        if (ch2 != 'u') {
286	            throw expectedChar(ch2, 'u');
287	        }
288	        int ch3 = read();
289	        if (ch3 != 'e') {
290	            throw expectedChar(ch3, 'e');
291	        }
292	    }
293	
294	    private void readFalse() {
295	        int ch1 = read();
296	        if (ch1 != 'a') {
297	            throw expectedChar(ch1, 'a');
298	        }
299	        int ch2 = read();
300	        if (ch2 != 'l') {
301	            throw expectedChar(ch2, 'l');
302	        }
303	        int ch3 = read();
304	        if (ch3 != 's') {
305	            throw expectedChar(ch3, 's');
306	        }
307	        int ch4 = read();
308	        if (ch4 != 'e') {
309	            throw expectedChar(ch4, 'e');
310	        }
311	    }
312	
313	    private void readNull() {
314	        int ch1 = read();
315	        if (ch1 != 'u') {
316	            throw expectedChar(ch1, 'u');
317	        }
318	        int ch2 = read();
319	        if (ch2 != 'l') {
320	            throw expectedChar(ch2, 'l');
321	        }
322	        int ch3 = read();
323	        if (ch3 != 'l') {
