332	    JsonToken nextToken() {
333	        reset();
334	        int ch = read();
335	
336	        // whitespace
337	        while (ch == 0x20 || ch == 0x09 || ch == 0x0a || ch == 0x0d) {
338	            if (ch == '\r') {
339	                ++lineNo;
340	                ch = read();
341	                if (ch == '\n') {
