343	                } else {
344	                    lastLineOffset = bufferOffset+readBegin-1;
345	                    continue;
346	                }
347	            } else if (ch == '\n') {
348	                ++lineNo;
349	                lastLineOffset = bufferOffset+readBegin;
350	            }
