526	                                sourceLen, jsonContext.bigDecimalLengthLimit()));
527	            }
528	            bd = new BigDecimal(buf, storeBegin, sourceLen);
529	        }
530	        return bd;
531	    }
532	
533	    int getInt() {
534	        // no need to create BigDecimal for common integer values (1-9 digits)
535	        int storeLen = storeEnd-storeBegin;
536	        if (!fracOrExp && (storeLen <= 9 || (minus && storeLen <= 10))) {
537	            int num = 0;
538	            int i = minus ? 1 : 0;
539	            for(; i < storeLen; i++) {
540	                num = num * 10 + (buf[storeBegin+i] - '0');
541	            }
542	            return minus ? -num : num;
543	        } else {
544	            return getBigDecimal().intValue();
545	        }
546	    }
547	
548	    long getLong() {
549	        // no need to create BigDecimal for common integer values (1-18 digits)
550	        int storeLen = storeEnd-storeBegin;
551	        if (!fracOrExp && (storeLen <= 18 || (minus && storeLen <= 19))) {
552	            long num = 0;
553	            int i = minus ? 1 : 0;
554	            for(; i < storeLen; i++) {
555	                num = num * 10 + (buf[storeBegin+i] - '0');
556	            }
557	            return minus ? -num : num;
558	        } else {
559	            return getBigDecimal().longValue();
560	        }
561	    }
562	
563	    // returns true for common integer values (1-9 digits).
564	    // So there are cases it will return false even though the number is int
565	    boolean isDefinitelyInt() {
566	        int storeLen = storeEnd-storeBegin;
567	        return !fracOrExp && (storeLen <= 9 || (minus && storeLen <= 10));
568	    }
569	
570	    // returns true for common long values (1-18 digits).
571	    // So there are cases it will return false even though the number is long
572	    boolean isDefinitelyLong() {
573	    	int storeLen = storeEnd-storeBegin;
574	    	return !fracOrExp && (storeLen <= 18 || (minus && storeLen <= 19));
575	    }
576	
577	    boolean isIntegral() {
578	        return !fracOrExp || getBigDecimal().scale() == 0;
579	    }
580	
581	    @Override
582	    public void close() throws IOException {
583	        if (!closed) {
584	            reader.close();
585	            jsonContext.bufferPool().recycle(buf);
586	            closed = true;
587	        }
588	    }
