590	    private JsonParsingException unexpectedChar(int ch) {
591	        JsonLocation location = getLastCharLocation();
592	        return new JsonParsingException(
593	            JsonMessages.TOKENIZER_UNEXPECTED_CHAR(ch, location), location);
594	    }
595	
596	    private JsonParsingException expectedChar(int unexpected, char expected) {
597	        JsonLocation location = getLastCharLocation();
598	        return new JsonParsingException(
599	                JsonMessages.TOKENIZER_EXPECTED_CHAR(unexpected, location, expected), location);
600	    }
