264	package org.eclipse.parsson;
265	
266	import org.eclipse.parsson.api.BufferPool;
267	
268	import java.lang.ref.WeakReference;
269	import java.util.concurrent.ConcurrentLinkedQueue;
270	
271	/**
272	 * char[] pool that pool instances of char[] which are expensive to create.
273	 *
274	 * @author Jitendra Kotamraju
275	 */
276	class BufferPoolImpl implements BufferPool {
277	
278	    // volatile since multiple threads may access queue reference
279	    private volatile WeakReference<ConcurrentLinkedQueue<char[]>> queue;
280	
281	    /**
282	     * Gets a new object from the pool.
283	     *
284	     * <p>
285	     * If no object is available in the pool, this method creates a new one.
286	     *
287	     * @return
288	     *      always non-null.
289	     */
290	    @Override
291	    public final char[] take() {
292	        char[] t = getQueue().poll();
293	        if (t==null)
294	            return new char[4096];
295	        return t;
296	    }
297	
298	    private ConcurrentLinkedQueue<char[]> getQueue() {
299	        WeakReference<ConcurrentLinkedQueue<char[]>> q = queue;
300	        if (q != null) {
301	            ConcurrentLinkedQueue<char[]> d = q.get();
302	            if (d != null)
303	                return d;
304	        }
305	
306	        // overwrite the queue
307	        ConcurrentLinkedQueue<char[]> d = new ConcurrentLinkedQueue<>();
308	        queue = new WeakReference<>(d);
309	
310	        return d;
311	    }
312	
313	    /**
314	     * Returns an object back to the pool.
315	     */
316	    @Override
317	    public final void recycle(char[] t) {
318	        getQueue().offer(t);
319	    }
320	
321	}

