 16	
 17	package org.eclipse.parsson;
 18	
 19	import java.io.IOException;
 20	import java.io.InputStream;
 21	import java.io.InputStreamReader;
 22	import java.io.Reader;
 23	import java.math.BigDecimal;
 24	import java.nio.charset.Charset;
 25	import java.util.AbstractMap;
 26	import java.util.Map;
 27	import java.util.NoSuchElementException;
 28	import java.util.Spliterator;
 29	import java.util.Spliterators;
 30	import java.util.function.Consumer;
 31	import java.util.stream.Stream;
 32	import java.util.stream.StreamSupport;
 33	
 34	import jakarta.json.JsonArray;
 35	import jakarta.json.JsonArrayBuilder;
 36	import jakarta.json.JsonException;
 37	import jakarta.json.JsonObject;
 38	import jakarta.json.JsonObjectBuilder;
 39	import jakarta.json.JsonValue;
 40	import jakarta.json.stream.JsonLocation;
 41	import jakarta.json.stream.JsonParser;
 42	import jakarta.json.stream.JsonParsingException;
 43	
 44	import org.eclipse.parsson.JsonTokenizer.JsonToken;
 45	
 46	/**
 47	 * JSON parser implementation. NoneContext, ArrayContext, ObjectContext is used
 48	 * to go to next parser state.
 49	 *
 50	 * @author Jitendra Kotamraju
 51	 * @author Kin-man Chung
 52	 */
 53	public class JsonParserImpl implements JsonParser {
 54	
 55	    private Context currentContext = new NoneContext();
 56	    private Event currentEvent;
 57	
 58	    private final Stack stack;
 59	    private final JsonTokenizer tokenizer;
 60	    private boolean closed = false;
 61	
 62	    private final JsonContext jsonContext;
 63	
 64	    public JsonParserImpl(Reader reader, JsonContext jsonContext) {
 65	        this.jsonContext = jsonContext;
 66	        stack = new Stack(jsonContext.depthLimit());
 67	        this.tokenizer = new JsonTokenizer(reader, jsonContext);
 68	    }
 69	
 70	    public JsonParserImpl(InputStream in, JsonContext jsonContext) {
 71	        this.jsonContext = jsonContext;
 72	        stack = new Stack(jsonContext.depthLimit());
 73	        UnicodeDetectingInputStream uin = new UnicodeDetectingInputStream(in);
 74	        this.tokenizer = new JsonTokenizer(new InputStreamReader(uin, uin.getCharset()), jsonContext);
 75	    }
 76	
 77	    public JsonParserImpl(InputStream in, Charset encoding, JsonContext jsonContext) {
 78	        this.jsonContext = jsonContext;
 79	        stack = new Stack(jsonContext.depthLimit());
 80	        this.tokenizer = new JsonTokenizer(new InputStreamReader(in, encoding), jsonContext);
 81	    }
 82	
 83	    @Override
 84	    public String getString() {
 85	        if (currentEvent == Event.KEY_NAME || currentEvent == Event.VALUE_STRING
 86	                || currentEvent == Event.VALUE_NUMBER) {
 87	            return tokenizer.getValue();
 88	        }
 89	        throw new IllegalStateException(
 90	                JsonMessages.PARSER_GETSTRING_ERR(currentEvent));
 91	    }
 92	
 93	    @Override
 94	    public boolean isIntegralNumber() {
 95	        if (currentEvent != Event.VALUE_NUMBER) {
 96	            throw new IllegalStateException(
 97	                    JsonMessages.PARSER_ISINTEGRALNUMBER_ERR(currentEvent));
 98	        }
 99	        return tokenizer.isIntegral();
100	    }
101	
102	    @Override
103	    public int getInt() {
104	        if (currentEvent != Event.VALUE_NUMBER) {
105	            throw new IllegalStateException(
106	                    JsonMessages.PARSER_GETINT_ERR(currentEvent));
107	        }
108	        return tokenizer.getInt();
109	    }
110	
111	    boolean isDefinitelyInt() {
112	        return tokenizer.isDefinitelyInt();
113	    }
114	
115	    boolean isDefinitelyLong() {
116	        return tokenizer.isDefinitelyLong();
117	    }
118	
119	    @Override
120	    public long getLong() {
121	        if (currentEvent != Event.VALUE_NUMBER) {
122	            throw new IllegalStateException(
123	                    JsonMessages.PARSER_GETLONG_ERR(currentEvent));
124	        }
125	        return tokenizer.getLong();
126	    }
127	
128	    @Override
129	    public BigDecimal getBigDecimal() {
130	        if (currentEvent != Event.VALUE_NUMBER) {
131	            throw new IllegalStateException(
132	                    JsonMessages.PARSER_GETBIGDECIMAL_ERR(currentEvent));
133	        }
134	        return tokenizer.getBigDecimal();
135	    }
136	
137	    @Override
138	    public JsonArray getArray() {
139	        if (currentEvent != Event.START_ARRAY) {
140	            throw new IllegalStateException(
141	                JsonMessages.PARSER_GETARRAY_ERR(currentEvent));
142	        }
143	        return getArray(new JsonArrayBuilderImpl(jsonContext));
144	    }
145	
146	    @Override
147	    public JsonObject getObject() {
148	        if (currentEvent != Event.START_OBJECT) {
149	            throw new IllegalStateException(
150	                JsonMessages.PARSER_GETOBJECT_ERR(currentEvent));
151	        }
152	        return getObject(new JsonObjectBuilderImpl(jsonContext));
153	    }
154	
155	    @Override
156	    public JsonValue getValue() {
157	        switch (currentEvent) {
158	            case START_ARRAY:
159	                return getArray(new JsonArrayBuilderImpl(jsonContext));
160	            case START_OBJECT:
161	                return getObject(new JsonObjectBuilderImpl(jsonContext));
162	            case KEY_NAME:
163	            case VALUE_STRING:
164	                return new JsonStringImpl(getCharSequence());
165	            case VALUE_NUMBER:
166	                if (isDefinitelyInt()) {
167	                    return JsonNumberImpl.getJsonNumber(getInt(), jsonContext.bigIntegerScaleLimit());
168	                } else if (isDefinitelyLong()) {
169	                    return JsonNumberImpl.getJsonNumber(getLong(), jsonContext.bigIntegerScaleLimit());
170	                }
171	                return JsonNumberImpl.getJsonNumber(getBigDecimal(), jsonContext.bigIntegerScaleLimit());
172	            case VALUE_TRUE:
173	                return JsonValue.TRUE;
174	            case VALUE_FALSE:
175	                return JsonValue.FALSE;
176	            case VALUE_NULL:
177	                return JsonValue.NULL;
178	            case END_ARRAY:
179	            case END_OBJECT:
180	            default:
181	                throw new IllegalStateException(JsonMessages.PARSER_GETVALUE_ERR(currentEvent));
182	        }
183	    }
184	
185	    @Override
186	    public Stream<JsonValue> getArrayStream() {
187	        if (currentEvent != Event.START_ARRAY) {
188	            throw new IllegalStateException(
189	                JsonMessages.PARSER_GETARRAY_ERR(currentEvent));
190	        }
191	        Spliterator<JsonValue> spliterator =
192	                new Spliterators.AbstractSpliterator<JsonValue>(Long.MAX_VALUE, Spliterator.ORDERED) {
193	            @Override
194	            public Spliterator<JsonValue> trySplit() {
195	                return null;
196	            }
197	            @Override
198	            public boolean tryAdvance(Consumer<? super JsonValue> action) {
199	                if (action == null) {
200	                    throw new NullPointerException();
201	                }
202	                if (! hasNext()) {
203	                    return false;
204	                }
205	                if (next() == JsonParser.Event.END_ARRAY) {
206	                    return false;
207	                }
208	                action.accept(getValue());
209	                return true;
210	            }
211	        };
212	        return StreamSupport.stream(spliterator, false);
213	    }
214	
215	    @Override
216	    public Stream<Map.Entry<String, JsonValue>> getObjectStream() {
217	        if (currentEvent != Event.START_OBJECT) {
218	            throw new IllegalStateException(
219	                JsonMessages.PARSER_GETOBJECT_ERR(currentEvent));
220	        }
221	        Spliterator<Map.Entry<String, JsonValue>> spliterator =
222	                new Spliterators.AbstractSpliterator<Map.Entry<String, JsonValue>>(Long.MAX_VALUE, Spliterator.ORDERED) {
223	            @Override
224	            public Spliterator<Map.Entry<String,JsonValue>> trySplit() {
225	                return null;
226	            }
227	            @Override
228	            public boolean tryAdvance(Consumer<? super Map.Entry<String, JsonValue>> action) {
229	                if (action == null) {
230	                    throw new NullPointerException();
231	                }
232	                if (! hasNext()) {
233	                    return false;
234	                }
235	                JsonParser.Event e = next();
236	                if (e == JsonParser.Event.END_OBJECT) {
237	                    return false;
238	                }
239	                if (e != JsonParser.Event.KEY_NAME) {
240	                    throw new JsonException(JsonMessages.INTERNAL_ERROR());
241	                }
242	                String key = getString();
243	                if (! hasNext()) {
244	                    throw new JsonException(JsonMessages.INTERNAL_ERROR());
245	                }
246	                next();
247	                JsonValue value = getValue();
248	                action.accept(new AbstractMap.SimpleImmutableEntry<>(key, value));
249	                return true;
250	            }
251	        };
252	        return StreamSupport.stream(spliterator, false);
253	    }
254	
255	    @Override
256	    public Stream<JsonValue> getValueStream() {
257	        if (! (currentContext instanceof NoneContext)) {
258	            throw new IllegalStateException(
259	                JsonMessages.PARSER_GETVALUESTREAM_ERR());
260	        }
261	        Spliterator<JsonValue> spliterator =
262	                new Spliterators.AbstractSpliterator<JsonValue>(Long.MAX_VALUE, Spliterator.ORDERED) {
263	            @Override
264	            public Spliterator<JsonValue> trySplit() {
265	                return null;
266	            }
267	            @Override
268	            public boolean tryAdvance(Consumer<? super JsonValue> action) {
269	                if (action == null) {
270	                    throw new NullPointerException();
271	                }
272	                if (! hasNext()) {
273	                    return false;
274	                }
275	                next();
276	                action.accept(getValue());
277	                return true;
278	            }
279	        };
280	        return StreamSupport.stream(spliterator, false);
281	    }
282	
283	    @Override
284	    public void skipArray() {
285	        if (currentEvent == Event.START_ARRAY) {
286	            currentContext.skip();
287	            currentContext = stack.pop();
288	            currentEvent = Event.END_ARRAY;
289	        }
290	    }
291	
292	    @Override
293	    public void skipObject() {
294	        if (currentEvent == Event.START_OBJECT) {
295	            currentContext.skip();
296	            currentContext = stack.pop();
297	            currentEvent = Event.END_OBJECT;
298	        }
299	    }
300	
301	    private JsonArray getArray(JsonArrayBuilder builder) {
302	        while(hasNext()) {
303	            JsonParser.Event e = next();
304	            if (e == JsonParser.Event.END_ARRAY) {
305	                return builder.build();
306	            }
307	            builder.add(getValue());
308	        }
309	        throw parsingException(JsonToken.EOF, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL, SQUARECLOSE]");
310	    }
311	
312	    private CharSequence getCharSequence() {
313	      if (currentEvent == Event.KEY_NAME || currentEvent == Event.VALUE_STRING
314	              || currentEvent == Event.VALUE_NUMBER) {
315	          return tokenizer.getCharSequence();
316	      }
317	      throw new IllegalStateException(JsonMessages.PARSER_GETSTRING_ERR(currentEvent));
318	  }
319	
320	    private JsonObject getObject(JsonObjectBuilder builder) {
321	        while(hasNext()) {
322	            JsonParser.Event e = next();
323	            if (e == JsonParser.Event.END_OBJECT) {
324	                return builder.build();
325	            }
326	            String key = getString();
327	            next();
328	            builder.add(key, getValue());
329	        }
330	        throw parsingException(JsonToken.EOF, "[STRING, CURLYCLOSE]");
331	    }
332	
333	    @Override
334	    public JsonLocation getLocation() {
335	        return tokenizer.getLocation();
336	    }
337	
338	    public JsonLocation getLastCharLocation() {
339	        return tokenizer.getLastCharLocation();
340	    }
341	
342	    @Override
343	    public boolean hasNext() {
344	        if (stack.isEmpty() && (currentEvent != null && currentEvent.compareTo(Event.KEY_NAME) > 0)) {
345	            JsonToken token = tokenizer.nextToken();
346	            if (token != JsonToken.EOF) {
347	                throw new JsonParsingException(JsonMessages.PARSER_EXPECTED_EOF(token),
348	                        getLastCharLocation());
349	            }
350	            return false;
351	        } else if (!stack.isEmpty() && !tokenizer.hasNextToken()) {
352	            currentEvent = currentContext.getNextEvent();
353	            return false;
354	        }
355	        return true;
356	    }
357	
358	    @Override
359	    public Event next() {
360	        if (!hasNext()) {
361	            throw new NoSuchElementException();
362	        }
363	        return currentEvent = currentContext.getNextEvent();
364	    }
365	
366	    @Override
367	    public Event currentEvent() {
368	        return currentEvent;
369	    }
370	
371	    @Override
372	    public void close() {
373	        if (!closed) {
374	            try {
375	                tokenizer.close();
376	                closed = true;
377	            } catch (IOException e) {
378	                throw new JsonException(JsonMessages.PARSER_TOKENIZER_CLOSE_IO(), e);
379	            }
380	        }
381	    }
382	
383	    // Using the optimized stack impl as we don't require other things
384	    // like iterator etc.
385	    private static final class Stack {
386	        int size = 0;
387	        final int limit;
388	        private Context head;
389	
390	        Stack(int size) {
391	            this.limit = size;
392	        }
393	
394	        private void push(Context context) {
395	            if (++size >= limit) {
396	                throw new RuntimeException(JsonMessages.PARSER_INPUT_NESTED_TOO_DEEP(size));
397	            }
398	            context.next = head;
399	            head = context;
400	        }
401	
402	        private Context pop() {
403	            if (head == null) {
404	                throw new NoSuchElementException();
405	            }
406	            size--;
407	            Context temp = head;
408	            head = head.next;
409	            return temp;
410	        }
411	
412	        private Context peek() {
413	            return head;
414	        }
415	
416	        private boolean isEmpty() {
417	            return head == null;
418	        }
419	    }
420	
421	    private abstract static class Context {
422	        Context next;
423	        abstract Event getNextEvent();
424	        abstract void skip();
425	    }
426	
427	    private final class NoneContext extends Context {
428	        @Override
429	        public Event getNextEvent() {
430	            // Handle 1. {   2. [   3. value
431	            JsonToken token = tokenizer.nextToken();
432	            if (token == JsonToken.CURLYOPEN) {
433	                stack.push(currentContext);
434	                currentContext = new ObjectContext();
435	                return Event.START_OBJECT;
436	            } else if (token == JsonToken.SQUAREOPEN) {
437	                stack.push(currentContext);
438	                currentContext = new ArrayContext();
439	                return Event.START_ARRAY;
440	            } else if (token.isValue()) {
441	                return token.getEvent();
442	            }
443	            throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
444	        }
445	
446	        @Override
447	        void skip() {
448	            // no-op
449	        }
450	    }
451	
452	    private JsonParsingException parsingException(JsonToken token, String expectedTokens) {
453	        JsonLocation location = getLastCharLocation();
454	        return new JsonParsingException(
455	                JsonMessages.PARSER_INVALID_TOKEN(token, location, expectedTokens), location);
456	    }
457	
458	    private final class ObjectContext extends Context {
459	        private boolean firstValue = true;
460	
461	        /*
462	         * Some more things could be optimized. For example, instead
463	         * tokenizer.nextToken(), one could use tokenizer.matchColonToken() to
464	         * match ':'. That might optimize a bit, but will fragment nextToken().
465	         * I think the current one is more readable.
466	         *
467	         */
468	        @Override
469	        public Event getNextEvent() {
470	            // Handle 1. }   2. name:value   3. ,name:value
471	            JsonToken token = tokenizer.nextToken();
472	            if (token == JsonToken.EOF) {
473	                switch (currentEvent) {
474	                    case START_OBJECT:
475	                        throw parsingException(token, "[STRING, CURLYCLOSE]");
476	                    case KEY_NAME:
477	                        throw parsingException(token, "[COLON]");
478	                    default:
479	                        throw parsingException(token, "[COMMA, CURLYCLOSE]");
480	                }
481	            } else if (currentEvent == Event.KEY_NAME) {
482	                // Handle 1. :value
483	                if (token != JsonToken.COLON) {
484	                    throw parsingException(token, "[COLON]");
485	                }
486	                token = tokenizer.nextToken();
487	                if (token.isValue()) {
488	                    return token.getEvent();
489	                } else if (token == JsonToken.CURLYOPEN) {
490	                    stack.push(currentContext);
491	                    currentContext = new ObjectContext();
492	                    return Event.START_OBJECT;
493	                } else if (token == JsonToken.SQUAREOPEN) {
494	                    stack.push(currentContext);
495	                    currentContext = new ArrayContext();
496	                    return Event.START_ARRAY;
497	                }
498	                throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
499	            } else {
500	                // Handle 1. }   2. name   3. ,name
501	                if (token == JsonToken.CURLYCLOSE) {
502	                    currentContext = stack.pop();
503	                    return Event.END_OBJECT;
504	                }
505	                if (firstValue) {
506	                    firstValue = false;
507	                } else {
508	                    if (token != JsonToken.COMMA) {
509	                        throw parsingException(token, "[COMMA]");
510	                    }
511	                    token = tokenizer.nextToken();
512	                }
513	                if (token == JsonToken.STRING) {
514	                    return Event.KEY_NAME;
515	                }
516	                throw parsingException(token, "[STRING]");
517	            }
518	        }
519	
520	        @Override
521	        void skip() {
522	            JsonToken token;
523	            int depth = 1;
524	            do {
525	                token = tokenizer.nextToken();
526	                switch (token) {
527	                    case CURLYCLOSE:
528	                        depth--;
529	                        break;
530	                    case CURLYOPEN:
531	                        depth++;
532	                        break;
533	                }
534	            } while (!(token == JsonToken.CURLYCLOSE && depth == 0));
535	        }
536	
537	    }
538	
539	    private final class ArrayContext extends Context {
540	        private boolean firstValue = true;
541	
542	        // Handle 1. ]   2. value   3. ,value
543	        @Override
544	        public Event getNextEvent() {
545	            JsonToken token = tokenizer.nextToken();
546	            if (token == JsonToken.EOF) {
547	                switch (currentEvent) {
548	                    case START_ARRAY:
549	                        throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
550	                    default:
551	                        throw parsingException(token, "[COMMA, CURLYCLOSE]");
552	                }
553	            }
554	            if (token == JsonToken.SQUARECLOSE) {
555	                currentContext = stack.pop();
556	                return Event.END_ARRAY;
557	            }
558	            if (firstValue) {
559	                firstValue = false;
560	            } else {
561	                if (token != JsonToken.COMMA) {
562	                    throw parsingException(token, "[COMMA]");
563	                }
564	                token = tokenizer.nextToken();
565	            }
566	            if (token.isValue()) {
567	                return token.getEvent();
568	            } else if (token == JsonToken.CURLYOPEN) {
569	                stack.push(currentContext);
570	                currentContext = new ObjectContext();
571	                return Event.START_OBJECT;
572	            } else if (token == JsonToken.SQUAREOPEN) {
573	                stack.push(currentContext);
574	                currentContext = new ArrayContext();
575	                return Event.START_ARRAY;
576	            }
577	            throw parsingException(token, "[CURLYOPEN, SQUAREOPEN, STRING, NUMBER, TRUE, FALSE, NULL]");
578	        }
579	
580	        @Override
581	        void skip() {
582	            JsonToken token;
583	            int depth = 1;
584	            do {
585	                token = tokenizer.nextToken();
586	                switch (token) {
587	                    case SQUARECLOSE:
588	                        depth--;
589	                        break;
590	                    case SQUAREOPEN:
591	                        depth++;
592	                        break;
593	                }
594	            } while (!(token == JsonToken.SQUARECLOSE && depth == 0));
595	        }
596	    }
597	
598	}

