 88	    // Using own buffering mechanism as JDK's BufferedWriter uses synchronized
 89	    // methods. Also, flushBuffer() is useful when you don't want to actually
 90	    // flush the underlying output source
 91	    private final char buf[];     // capacity >= INT_MIN_VALUE_CHARS.length
