685	    void getChars(CharSequence str, int srcBegin, int srcEnd, char[] dst, int dstBegin) {
686	      int length = srcEnd - srcBegin;
687	      for (int i = 0 ; i < length ; i++) {
688	        int srcIdx = srcBegin + i;
