642	    // byte stream, an OuputStreamWriter is created and that buffers too.
643	    // We may need to call OutputStreamWriter#flushBuffer() using
644	    // reflection if that is really required (commented out below)
645	    void flushBuffer() {
646	        try {
647	            if (len > 0) {
648	                writer.write(buf, 0, len);
649	                len = 0;
650	            }
651	        } catch (IOException ioe) {
652	            throw new JsonException(JsonMessages.GENERATOR_WRITE_IO_ERR(), ioe);
653	        }
654	    }
