303	package org.eclipse.parsson;
304	
305	import jakarta.json.JsonArrayBuilder;
306	import jakarta.json.JsonObjectBuilder;
307	import jakarta.json.JsonValue;
308	import java.math.BigDecimal;
309	import java.math.BigInteger;
310	import java.util.Arrays;
311	import java.util.Collection;
312	import java.util.Map;
313	
314	/**
315	 * Util for transforming a Map to a Json objects.
316	 *
317	 * @author asotobu
318	 */
319	public final class MapUtil {
320	
321	    private MapUtil() {
322	        super();
323	    }
324	
325	    static JsonValue handle(Object value, JsonContext jsonContext) {
326	        if (value == null) {
327	            return JsonValue.NULL;
328	        } else if (value instanceof JsonValue) {
329	            return (JsonValue) value;
330	        } else if (value instanceof JsonArrayBuilder) {
331	            return ((JsonArrayBuilder) value).build();
332	        } else if (value instanceof JsonObjectBuilder) {
333	            return ((JsonObjectBuilder) value).build();
334	        } else if (value instanceof BigDecimal) {
335	            return JsonNumberImpl.getJsonNumber((BigDecimal) value, jsonContext.bigIntegerScaleLimit());
336	        } else if (value instanceof BigInteger) {
337	            return JsonNumberImpl.getJsonNumber((BigInteger) value, jsonContext.bigIntegerScaleLimit());
338	        } else if (value instanceof Boolean) {
339	            Boolean b = (Boolean) value;
340	            return b ? JsonValue.TRUE : JsonValue.FALSE;
341	        } else if (value instanceof Double) {
342	            return JsonNumberImpl.getJsonNumber((Double) value, jsonContext.bigIntegerScaleLimit());
343	        } else if (value instanceof Integer) {
344	            return JsonNumberImpl.getJsonNumber((Integer) value, jsonContext.bigIntegerScaleLimit());
345	        } else if (value instanceof Long) {
346	            return JsonNumberImpl.getJsonNumber((Long) value, jsonContext.bigIntegerScaleLimit());
347	        } else if (value instanceof String) {
348	            return new JsonStringImpl((String) value);
349	        } else if (value instanceof Collection) {
350	            Collection<?> collection = (Collection<?>) value;
351	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(collection, jsonContext);
352	            return jsonArrayBuilder.build();
353	        } else if (value instanceof Map) {
354	            @SuppressWarnings("unchecked")
355	            JsonObjectBuilder object = new JsonObjectBuilderImpl((Map<String, Object>) value, jsonContext);
356	            return object.build();
357	        } else if (value instanceof Object[]) {
358	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(Arrays.asList((Object[]) value), jsonContext);
359	            return jsonArrayBuilder.build();
360	        } else if (value instanceof int[]) {
361	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
362	            for (int d : (int[]) value) {
363	                jsonArrayBuilder.add(d);
364	            }
365	            return jsonArrayBuilder.build();
366	        } else if (value instanceof long[]) {
367	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
368	            for (long d : (long[]) value) {
369	                jsonArrayBuilder.add(d);
370	            }
371	            return jsonArrayBuilder.build();
372	        } else if (value instanceof double[]) {
373	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
374	            for (double d : (double[]) value) {
375	                jsonArrayBuilder.add(d);
376	            }
377	            return jsonArrayBuilder.build();
378	        } else if (value instanceof boolean[]) {
379	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
380	            for (boolean d : (boolean[]) value) {
381	                jsonArrayBuilder.add(d);
382	            }
383	            return jsonArrayBuilder.build();
384	        } else if (value instanceof char[]) {
385	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
386	            for (char d : (char[]) value) {
387	                jsonArrayBuilder.add(d);
388	            }
389	            return jsonArrayBuilder.build();
390	        } else if (value instanceof float[]) {
391	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
392	            for (float d : (float[]) value) {
393	                jsonArrayBuilder.add(d);
394	            }
395	            return jsonArrayBuilder.build();
396	        } else if (value instanceof byte[]) {
397	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
398	            for (byte d : (byte[]) value) {
399	                jsonArrayBuilder.add(d);
400	            }
401	            return jsonArrayBuilder.build();
402	        } else if (value instanceof short[]) {
403	            JsonArrayBuilder jsonArrayBuilder = new JsonArrayBuilderImpl(jsonContext);
404	            for (short d : (short[]) value) {
405	                jsonArrayBuilder.add(d);
406	            }
407	            return jsonArrayBuilder.build();
408	        }
409	
410	        throw new IllegalArgumentException(String.format("Type %s is not supported.", value.getClass()));
411	    }
