 59	    static JsonNumber getJsonNumber(BigDecimal value, int bigIntegerScaleLimit) {
 60	        if (value == null) {
 61	            throw new NullPointerException("Value is null");
 62	        }
 63	        return new JsonBigDecimalNumber(value, bigIntegerScaleLimit);
 64	    }
