 66	    static JsonNumber getJsonNumber(Number value, int bigIntegerScaleLimit) {
 67	        if (value == null) {
 68	            throw new NullPointerException("Value is null");
 69	        }
 70	        if (value instanceof Integer) {
 71	            return getJsonNumber(value.intValue(), bigIntegerScaleLimit);
 72	        } else if (value instanceof Long) {
 73	            return getJsonNumber(value.longValue(), bigIntegerScaleLimit);
 74	        } else if (value instanceof Double) {
 75	            return getJsonNumber(value.doubleValue(), bigIntegerScaleLimit);
 76	        } else if (value instanceof BigInteger) {
 77	            return getJsonNumber((BigInteger) value, bigIntegerScaleLimit);
 78	        } else if (value instanceof BigDecimal) {
 79	            return getJsonNumber((BigDecimal) value, bigIntegerScaleLimit);
 80	        } else {
 81	            return new JsonNumberNumber(value, bigIntegerScaleLimit);
 82	        }
