363	final class JsonStringImpl implements JsonString {
364	
365	    private final CharSequence value;
366	
367	    JsonStringImpl(CharSequence value) {
368	        this.value = value;
369	    }
370	
371	    @Override
372	    public String getString() {
373	        return value.toString();
374	    }
375	
376	    @Override
377	    public CharSequence getChars() {
378	        return value;
379	    }
380	
381	    @Override
382	    public ValueType getValueType() {
383	        return ValueType.STRING;
384	    }
385	
386	    @Override
387	    public int hashCode() {
388	        return getString().hashCode();
389	    }
390	
391	    @Override
392	    public boolean equals(Object obj) {
393	        if (this == obj){
394	            return true;
395	        }
396	        if (!(obj instanceof JsonString)) {
397	            return false;
398	        }
399	        JsonString other = (JsonString)obj;
400	        return getString().equals(other.getString());
401	    }
402	
403	    @Override
404	    public String toString() {
405	        StringBuilder sb = new StringBuilder();
406	        sb.append('"');
407	
408	        for(int i = 0; i < value.length(); i++) {
409	            char c = value.charAt(i);
410	            // unescaped = %x20-21 | %x23-5B | %x5D-10FFFF
411	            if (c >= 0x20 && c <= 0x10ffff && c != 0x22 && c != 0x5c) {
412	                sb.append(c);
413	            } else {
414	                switch (c) {
415	                    case '"':
416	                    case '\\':
417	                        sb.append('\\'); sb.append(c);
418	                        break;
419	                    case '\b':
420	                        sb.append('\\'); sb.append('b');
421	                        break;
422	                    case '\f':
423	                        sb.append('\\'); sb.append('f');
424	                        break;
425	                    case '\n':
426	                        sb.append('\\'); sb.append('n');
427	                        break;
428	                    case '\r':
429	                        sb.append('\\'); sb.append('r');
430	                        break;
431	                    case '\t':
432	                        sb.append('\\'); sb.append('t');
433	                        break;
434	                    default:
435	                        String hex = "000" + Integer.toHexString(c);
436	                        sb.append("\\u").append(hex.substring(hex.length() - 4));
437	                }
438	            }
439	        }
440	
441	        sb.append('"');
442	        return sb.toString();
443	    }
444	}
