158	/**
159	 * A filter stream that detects the unicode encoding for the original
160	 * stream
161	 *
162	 * @author Jitendra Kotamraju
163	 */
164	class UnicodeDetectingInputStream extends FilterInputStream {
165	
166	    private static final Charset UTF_32LE = Charset.forName("UTF-32LE");
167	    private static final Charset UTF_32BE = Charset.forName("UTF-32BE");
168	
169	    private static final byte FF = (byte)0xFF;
170	    private static final byte FE = (byte)0xFE;
171	    private static final byte EF = (byte)0xEF;
172	    private static final byte BB = (byte)0xBB;
173	    private static final byte BF = (byte)0xBF;
174	    private static final byte NUL = (byte)0x00;
175	
176	    private final byte[] buf = new byte[4];
177	    private int bufLen;
178	    private int curIndex;
179	    private final Charset charset;
180	
181	    UnicodeDetectingInputStream(InputStream is) {
182	        super(is);
183	        charset = detectEncoding();
184	    }
185	
186	    Charset getCharset() {
187	        return charset;
188	    }
189	
190	    private void fillBuf() {
191	        int b1;
192	        int b2;
193	        int b3;
194	        int b4;
195	
196	        try {
197	            b1 = in.read();
198	            if (b1 == -1) {
199	                return;
200	            }
201	
202	            b2 = in.read();
203	            if (b2 == -1) {
204	                bufLen = 1;
205	                buf[0] = (byte)b1;
206	                return;
207	            }
208	
209	            b3 = in.read();
210	            if (b3 == -1) {
211	                bufLen = 2;
212	                buf[0] = (byte)b1;
213	                buf[1] = (byte)b2;
214	                return;
215	            }
216	
217	            b4 = in.read();
218	            if (b4 == -1) {
219	                bufLen = 3;
220	                buf[0] = (byte)b1;
221	                buf[1] = (byte)b2;
222	                buf[2] = (byte)b3;
223	                return;
224	            }
225	            bufLen = 4;
226	            buf[0] = (byte)b1;
227	            buf[1] = (byte)b2;
228	            buf[2] = (byte)b3;
229	            buf[3] = (byte)b4;
230	        } catch (IOException ioe) {
231	            throw new JsonException(JsonMessages.PARSER_INPUT_ENC_DETECT_IOERR(), ioe);
232	        }
233	    }
234	
235	    private Charset detectEncoding() {
236	        fillBuf();
237	        if (bufLen < 2) {
238	            throw new JsonException(JsonMessages.PARSER_INPUT_ENC_DETECT_FAILED());
239	        } else if (bufLen == 4) {
240	            // Use BOM to detect encoding
241	            if (buf[0] == NUL && buf[1] == NUL && buf[2] == FE && buf[3] == FF) {
242	                curIndex = 4;
243	                return UTF_32BE;
244	            } else if (buf[0] == FF && buf[1] == FE && buf[2] == NUL && buf[3] == NUL) {
245	                curIndex = 4;
246	                return UTF_32LE;
247	            } else if (buf[0] == FE && buf[1] == FF) {
248	                curIndex = 2;
249	                return StandardCharsets.UTF_16BE;
250	            } else if (buf[0] == FF && buf[1] == FE) {
251	                curIndex = 2;
252	                return StandardCharsets.UTF_16LE;
253	            } else if (buf[0] == EF && buf[1] == BB && buf[2] == BF) {
254	                curIndex = 3;
255	                return StandardCharsets.UTF_8;
256	            }
257	            // No BOM, just use JSON RFC's encoding algo to auto-detect
258	            if (buf[0] == NUL && buf[1] == NUL && buf[2] == NUL) {
259	                return UTF_32BE;
260	            } else if (buf[0] == NUL && buf[2] == NUL) {
261	                return StandardCharsets.UTF_16BE;
262	            } else if (buf[1] == NUL && buf[2] == NUL && buf[3] == NUL) {
263	                return UTF_32LE;
264	            } else if (buf[1] == NUL && buf[3] == NUL) {
265	                return StandardCharsets.UTF_16LE;
266	            }
267	        }
268	        return StandardCharsets.UTF_8;
269	    }
