324	/**
325	 * JsonWriter impl using generator.
326	 *
327	 * @author Jitendra Kotamraju
328	 */
329	class JsonWriterImpl implements JsonWriter {
330	
331	    private final JsonGeneratorImpl generator;
332	    private boolean writeDone;
333	    private final NoFlushOutputStream os;
334	
335	    JsonWriterImpl(Writer writer, JsonContext jsonContext) {
336	        this.generator = jsonContext.prettyPrinting()
337	                ? new JsonPrettyGeneratorImpl(writer, jsonContext)
338	                : new JsonGeneratorImpl(writer, jsonContext);
339	        this.os = null;
340	    }
341	
342	    JsonWriterImpl(OutputStream out, JsonContext jsonContext) {
343	        this(out, StandardCharsets.UTF_8, jsonContext);
344	    }
345	
346	    JsonWriterImpl(OutputStream out, Charset charset, JsonContext jsonContext) {
347	        // Decorating the given stream, so that buffered contents can be
348	        // written without actually flushing the stream.
349	        this.os = new NoFlushOutputStream(out);
350	        this.generator = jsonContext.prettyPrinting()
351	                ? new JsonPrettyGeneratorImpl(os, charset, jsonContext)
352	                : new JsonGeneratorImpl(os, charset, jsonContext);
353	    }
354	
355	    @Override
356	    public void writeArray(JsonArray array) {
357	        if (writeDone) {
358	            throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
359	        }
360	        writeDone = true;
361	        generator.writeStartArray();
362	        for(JsonValue value : array) {
363	            generator.write(value);
364	        }
365	        generator.writeEnd();
366	        // Flush the generator's buffered contents. This won't work for byte
367	        // streams as intermediary OutputStreamWriter buffers.
368	        generator.flushBuffer();
369	        // Flush buffered contents but not the byte stream. generator.flush()
370	        // does OutputStreamWriter#flushBuffer (package private) and underlying
371	        // byte stream#flush(). Here underlying stream's flush() is no-op.
372	        if (os != null) {
373	            generator.flush();
374	        }
375	    }
376	
377	    @Override
378	    public void writeObject(JsonObject object) {
379	        if (writeDone) {
380	            throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
381	        }
382	        writeDone = true;
383	        generator.writeStartObject();
384	        for(Map.Entry<String, JsonValue> e : object.entrySet()) {
385	            generator.write(e.getKey(), e.getValue());
386	        }
387	        generator.writeEnd();
388	        // Flush the generator's buffered contents. This won't work for byte
389	        // streams as intermediary OutputStreamWriter buffers.
390	        generator.flushBuffer();
391	        // Flush buffered contents but not the byte stream. generator.flush()
392	        // does OutputStreamWriter#flushBuffer (package private) and underlying
393	        // byte stream#flush(). Here underlying stream's flush() is no-op.
394	        if (os != null) {
395	            generator.flush();
396	        }
397	    }
398	
399	    @Override
400	    public void write(JsonStructure value) {
401	        if (value instanceof JsonArray) {
402	            writeArray((JsonArray)value);
403	        } else {
404	            writeObject((JsonObject)value);
405	        }
406	    }
407	
408	    @Override
409	    public void write(JsonValue value) {
410	        switch (value.getValueType()) {
411	            case OBJECT:
412	                writeObject((JsonObject) value);
413	                return;
414	            case ARRAY:
415	                writeArray((JsonArray) value);
416	                return;
417	            default:
418	                if (writeDone) {
419	                    throw new IllegalStateException(JsonMessages.WRITER_WRITE_ALREADY_CALLED());
420	                }
421	                writeDone = true;
422	                generator.write(value);
423	                generator.flushBuffer();
424	                if (os != null) {
425	                    generator.flush();
426	                }
427	        }
428	    }
429	
430	    @Override
431	    public void close() {
432	        writeDone = true;
433	        generator.close();
434	    }
435	
436	    private static final class NoFlushOutputStream extends FilterOutputStream {
437	        public NoFlushOutputStream(OutputStream out) {
438	            super(out);
439	        }
440	
441	        @Override
442	        public void write(byte b[], int off, int len) throws IOException {
443	            out.write(b, off ,len);
444	        }
445	
446	        @Override
447	        public void flush() {
448	            // no-op
449	        }
450	    }
451	
452	}

