273	        if (curIndex < bufLen) {
274	            return buf[curIndex++];
275	        }
276	        return in.read();
277	    }
278	
279	    @Override
280	    public int read(byte b[], int off, int len) throws IOException {
281	        if (curIndex < bufLen) {
282	            if (len == 0) {
283	                return 0;
284	            }
285	            if (off < 0 || len < 0 || len > b.length -off) {
286	                throw new IndexOutOfBoundsException();
287	            }
288	            int min = Math.min(bufLen-curIndex, len);
289	            System.arraycopy(buf, curIndex, b, off, min);
290	            curIndex += min;
291	            return min;
292	        }
293	        return in.read(b, off, len);
294	    }
