356	    private static enum DuplicateStrategy {
357	
358	        NONE(KeyStrategy.NONE) {
359	            @Override
360	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
361	                if (previous != null) {
362	                    throw new IllegalStateException(JsonMessages.DUPLICATE_KEY(name));
363	                } else {
364	                    return value;
365	                }
366	            }
367	        },
368	        FIRST(KeyStrategy.FIRST) {
369	            @Override
370	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
371	                if (previous != null) {
372	                    return previous;
373	                } else {
374	                    return value;
375	                }
376	            }
377	        },
378	        LAST(KeyStrategy.LAST) {
379	            @Override
380	            protected JsonValue getValue(String name, JsonValue value, JsonValue previous) {
381	                return value;
382	            }
383	        };
384	
385	        private final KeyStrategy property;
386	
387	        private DuplicateStrategy(KeyStrategy property) {
388	            this.property = property;
389	        }
390	        
391	        private static DuplicateStrategy strategyFromProperty(Object value, boolean rejectDuplicateKeys) {
392	            if (value != null) {
393	                for (DuplicateStrategy strategy : DuplicateStrategy.values()) {
394	                    if (strategy.property.equals(value)) {
395	                        return strategy;
396	                    }
397	                }
398	            }
399	            if (rejectDuplicateKeys) {
400	                return DuplicateStrategy.NONE;
401	            } else {
402	                return DuplicateStrategy.LAST;
403	            }
404	        }
405	        
406	        protected abstract JsonValue getValue(String name, JsonValue value, JsonValue previous);
407	    }
