148	        validateName(name);
149	        if (builder == null) {
150	            throw new NullPointerException(JsonMessages.OBJBUILDER_ARRAY_BUILDER_NULL());
151	        }
152	        putValueMap(name, builder.build());
153	        return this;
154	    }
155	
156	    @Override
157	    public JsonObjectBuilder addAll(JsonObjectBuilder builder) {
158	        if (builder == null) {
159	            throw new NullPointerException(JsonMessages.OBJBUILDER_OBJECT_BUILDER_NULL());
160	        }
161	        if (valueMap == null) {
162	            this.valueMap = new LinkedHashMap<>();
163	        }
164	        this.valueMap.putAll(builder.build());
165	        return this;
166	    }
167	
168	    @Override
169	    public JsonObjectBuilder remove(String name) {
170	        validateName(name);
171	        this.valueMap.remove(name);
172	        return this;
173	    }
174	
175	    @Override
176	    public JsonObject build() {
177	        Map<String, JsonValue> snapshot = (valueMap == null)
178	                ? Collections.<String, JsonValue>emptyMap()
179	                : Collections.unmodifiableMap(valueMap);
180	        valueMap = null;
181	        return new JsonObjectImpl(snapshot, jsonContext);
182	    }
183	
184	    private void populate(Map<String, ?> map) {
185	        final Set<String> fields = map.keySet();
186	        for (String field : fields) {
187	            Object value = map.get(field);
188	            if (value instanceof Optional) {
189	                ((Optional<?>) value).ifPresent(v ->
190	                        this.valueMap.put(field, MapUtil.handle(v, jsonContext)));
191	            } else {
192	                this.valueMap.put(field, MapUtil.handle(value, jsonContext));
193	            }
194	        }
195	    }
196	
197	    private void putValueMap(String name, JsonValue value) {
198	        if (valueMap == null) {
199	            this.valueMap = new LinkedHashMap<>();
200	        }
201	        JsonValue previousValue = valueMap.get(name);
202	        valueMap.put(name, duplicateStrategy.getValue(name, value, previousValue));
203	    }
204	
205	    private void validateName(String name) {
206	        if (name == null) {
207	            throw new NullPointerException(JsonMessages.OBJBUILDER_NAME_NULL());
208	        }
209	    }
210	
211	    private void validateValue(Object value) {
212	        if (value == null) {
213	            throw new NullPointerException(JsonMessages.OBJBUILDER_VALUE_NULL());
214	        }
215	    }
