217	    private static final class JsonObjectImpl extends AbstractMap<String, JsonValue> implements JsonObject {
218	        private final Map<String, JsonValue> valueMap;      // unmodifiable
219	        private final JsonContext jsonContext;
220	        private int hashCode;
221	
222	        JsonObjectImpl(Map<String, JsonValue> valueMap, JsonContext jsonContext) {
