 28	
 29	/**
 30	 * {@link JsonParser} implementation on top of JsonArray/JsonObject
 31	 *
 32	 * @author Jitendra Kotamraju
 33	 */
 34	class JsonStructureParser implements JsonParser {
 35	
 36	    private Scope current;
 37	    private Event state;
 38	    private final Deque<Scope> scopeStack = new ArrayDeque<>();
 39	
 40	    JsonStructureParser(JsonArray array) {
 41	        current = new ArrayScope(array);
 42	    }
 43	
 44	    JsonStructureParser(JsonObject object) {
 45	        current = new ObjectScope(object);
 46	    }
 47	
 48	    @Override
 49	    public String getString() {
 50	        switch (state) {
 51	            case KEY_NAME:
 52	                return ((ObjectScope)current).key;
 53	            case VALUE_STRING:
 54	                return ((JsonString)current.getJsonValue()).getString();
 55	            case VALUE_NUMBER:
 56	                return ((JsonNumber)current.getJsonValue()).toString();
 57	            default:
 58	                throw new IllegalStateException(JsonMessages.PARSER_GETSTRING_ERR(state));
 59	        }
 60	    }
 61	
 62	    @Override
 63	    public boolean isIntegralNumber() {
 64	        if (state == Event.VALUE_NUMBER) {
 65	            return ((JsonNumber)current.getJsonValue()).isIntegral();
 66	        }
 67	        throw new IllegalStateException(JsonMessages.PARSER_ISINTEGRALNUMBER_ERR(state));
 68	    }
 69	
 70	    @Override
 71	    public int getInt() {
 72	        if (state == Event.VALUE_NUMBER) {
 73	            return ((JsonNumber)current.getJsonValue()).intValue();
 74	        }
 75	        throw new IllegalStateException(JsonMessages.PARSER_GETINT_ERR(state));
 76	    }
 77	
 78	    @Override
 79	    public long getLong() {
 80	        if (state == Event.VALUE_NUMBER) {
 81	            return ((JsonNumber)current.getJsonValue()).longValue();
 82	        }
 83	        throw new IllegalStateException(JsonMessages.PARSER_GETLONG_ERR(state));
 84	    }
 85	
 86	    @Override
 87	    public BigDecimal getBigDecimal() {
 88	        if (state == Event.VALUE_NUMBER) {
 89	            return ((JsonNumber)current.getJsonValue()).bigDecimalValue();
 90	        }
 91	        throw new IllegalStateException(JsonMessages.PARSER_GETBIGDECIMAL_ERR(state));
 92	    }
 93	
 94	    @Override
 95	    public JsonLocation getLocation() {
 96	        return JsonLocationImpl.UNKNOWN;
 97	    }
 98	
 99	    @Override
100	    public boolean hasNext() {
101	        return !((state == Event.END_OBJECT || state == Event.END_ARRAY) && scopeStack.isEmpty());
102	    }
103	
104	    @Override
105	    public Event next() {
106	        if (!hasNext()) {
107	            throw new NoSuchElementException();
108	        }
109	        transition();
110	        return state;
111	    }
112	
113	    private void transition() {
114	        if (state == null) {
115	            state = current instanceof ArrayScope ? Event.START_ARRAY : Event.START_OBJECT;
116	        } else {
117	            if (state == Event.END_OBJECT || state == Event.END_ARRAY) {
118	                current = scopeStack.pop();
119	            }
120	            if (current instanceof ArrayScope) {
121	                if (current.hasNext()) {
122	                    current.next();
123	                    state = getState(current.getJsonValue());
124	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
125	                        scopeStack.push(current);
126	                        current = Scope.createScope(current.getJsonValue());
127	                    }
128	                } else {
129	                    state = Event.END_ARRAY;
130	                }
131	            } else {
132	                // ObjectScope
133	                if (state == Event.KEY_NAME) {
134	                    state = getState(current.getJsonValue());
135	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
136	                        scopeStack.push(current);
137	                        current = Scope.createScope(current.getJsonValue());
138	                    }
139	                } else {
140	                    if (current.hasNext()) {
141	                        current.next();
142	                        state = Event.KEY_NAME;
143	                    } else {
144	                        state = Event.END_OBJECT;
145	                    }
146	                }
147	            }
148	        }
149	    }
150	
151	    @Override
152	    public void close() {
153	        // no-op
154	    }
155	
156	    @Override
157	    public void skipObject() {
158	        if (current instanceof ObjectScope) {
159	            int depth = 1;
160	            do {
161	                if (state == Event.KEY_NAME) {
162	                    state = getState(current.getJsonValue());
163	                    switch (state) {
164	                        case START_OBJECT:
165	                            depth++;
166	                            break;
167	                        case END_OBJECT:
168	                            depth--;
169	                            break;
170	                        default:
171	                            //no-op
172	                    }
173	                } else {
174	                    if (current.hasNext()) {
175	                        current.next();
176	                        state = Event.KEY_NAME;
177	                    } else {
178	                        state = Event.END_OBJECT;
179	                        depth--;
180	                    }
181	                }
182	            } while (state != Event.END_OBJECT && depth > 0);
183	        }
184	    }
185	
186	    @Override
187	    public void skipArray() {
188	        if (current instanceof ArrayScope) {
189	            int depth = 1;
190	            do {
191	                if (current.hasNext()) {
192	                    current.next();
193	                    state = getState(current.getJsonValue());
194	                    switch (state) {
195	                        case START_ARRAY:
196	                            depth++;
197	                            break;
198	                        case END_ARRAY:
199	                            depth--;
200	                            break;
201	                        default:
202	                            //no-op
203	                    }
204	                } else {
205	                    state = Event.END_ARRAY;
206	                    depth--;
207	                }
208	            } while (!(state == Event.END_ARRAY && depth == 0));
209	        }
210	    }
211	
212	    private static Event getState(JsonValue value) {
213	        switch (value.getValueType()) {
214	            case ARRAY:
215	                return Event.START_ARRAY;
216	            case OBJECT:
217	                return Event.START_OBJECT;
218	            case STRING:
219	                return Event.VALUE_STRING;
220	            case NUMBER:
221	                return Event.VALUE_NUMBER;
222	            case TRUE:
223	                return Event.VALUE_TRUE;
224	            case FALSE:
225	                return Event.VALUE_FALSE;
226	            case NULL:
227	                return Event.VALUE_NULL;
228	            default:
229	                throw new JsonException(JsonMessages.PARSER_STATE_ERR(value.getValueType()));
230	        }
231	    }
232	
233	    private static abstract class Scope implements Iterator {
234	        abstract JsonValue getJsonValue();
235	
236	        static Scope createScope(JsonValue value) {
237	            if (value instanceof JsonArray) {
238	                return new ArrayScope((JsonArray)value);
239	            } else if (value instanceof JsonObject) {
240	                return new ObjectScope((JsonObject)value);
241	            }
242	            throw new JsonException(JsonMessages.PARSER_SCOPE_ERR(value));
243	        }
244	    }
245	
246	    private static class ArrayScope extends Scope {
247	        private final Iterator<JsonValue> it;
248	        private JsonValue value;
249	
250	        ArrayScope(JsonArray array) {
251	            this.it = array.iterator();
252	        }
253	
254	        @Override
255	        public boolean hasNext() {
256	            return it.hasNext();
257	        }
258	
259	        @Override
260	        public JsonValue next() {
261	            value = it.next();
262	            return value;
263	        }
264	
265	        @Override
266	        public void remove() {
267	            throw new UnsupportedOperationException();
268	        }
269	
270	        @Override
271	        JsonValue getJsonValue() {
272	            return value;
273	        }
274	
275	    }
276	
277	    private static class ObjectScope extends Scope {
278	        private final Iterator<Map.Entry<String, JsonValue>> it;
279	        private JsonValue value;
280	        private String key;
281	
282	        ObjectScope(JsonObject object) {
283	            this.it = object.entrySet().iterator();
284	        }
285	
286	        @Override
287	        public boolean hasNext() {
288	            return it.hasNext();
289	        }
290	
291	        @Override
292	        public Map.Entry<String, JsonValue> next() {
293	            Map.Entry<String, JsonValue> next = it.next();
294	            this.key = next.getKey();
295	            this.value = next.getValue();
296	            return next;
297	        }
298	
299	        @Override
300	        public void remove() {
301	            throw new UnsupportedOperationException();
302	        }
303	
304	        @Override
305	        JsonValue getJsonValue() {
306	            return value;
307	        }
308	
309	    }
310	
311	}
