113	    private void transition() {
114	        if (state == null) {
115	            state = current instanceof ArrayScope ? Event.START_ARRAY : Event.START_OBJECT;
116	        } else {
117	            if (state == Event.END_OBJECT || state == Event.END_ARRAY) {
118	                current = scopeStack.pop();
119	            }
120	            if (current instanceof ArrayScope) {
121	                if (current.hasNext()) {
122	                    current.next();
123	                    state = getState(current.getJsonValue());
124	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
125	                        scopeStack.push(current);
126	                        current = Scope.createScope(current.getJsonValue());
127	                    }
128	                } else {
129	                    state = Event.END_ARRAY;
130	                }
131	            } else {
132	                // ObjectScope
133	                if (state == Event.KEY_NAME) {
134	                    state = getState(current.getJsonValue());
135	                    if (state == Event.START_ARRAY || state == Event.START_OBJECT) {
136	                        scopeStack.push(current);
137	                        current = Scope.createScope(current.getJsonValue());
138	                    }
139	                } else {
140	                    if (current.hasNext()) {
141	                        current.next();
142	                        state = Event.KEY_NAME;
143	                    } else {
144	                        state = Event.END_OBJECT;
145	                    }
146	                }
147	            }
148	        }
149	    }
