236	        static Scope createScope(JsonValue value) {
237	            if (value instanceof JsonArray) {
238	                return new ArrayScope((JsonArray)value);
239	            } else if (value instanceof JsonObject) {
240	                return new ObjectScope((JsonObject)value);
241	            }
242	            throw new JsonException(JsonMessages.PARSER_SCOPE_ERR(value));
243	        }
