    28	public class TestUtils {
    29	
    30	    /**
    31	     * Creates an instance of JSON Merge Patch with empty context.
    32	     *
    33	     * @param patch JSON Merge Patch
    34	     * @return new JSON Merge Patch instance
    35	     */
    36	    public static JsonMergePatchImpl createJsonMergePatchImpl(JsonValue patch) {
    37	        return new JsonMergePatchImpl(patch, new JsonContext(null, new BufferPoolImpl()));
    38	    }
    39	
    40	    /**
    41	     * Reads the input JSON text and returns a JsonValue.
    42	     * <p>For convenience, single quotes as well as double quotes
    43	     * are allowed to delimit JSON strings. If single quotes are
    44	     * used, any quotes, single or double, in the JSON string must be
    45	     * escaped (prepend with a '\').
    46	     *
    47	     * @param jsonString the input JSON data
    48	     * @return the object model for {@code jsonString}
    49	     * @throws jakarta.json.stream.JsonParsingException if the input is not legal JSON text
    50	     */
    51	    public static JsonValue toJson(String jsonString) {
    52	        StringBuilder builder = new StringBuilder();
    53	        boolean single_context = false;
    54	        for (int i = 0; i < jsonString.length(); i++) {
    55	            char ch = jsonString.charAt(i);
    56	            if (ch == '\\') {
    57	                i = i + 1;
    58	                if (i < jsonString.length()) {
    59	                    ch = jsonString.charAt(i);
    60	                    if (!(single_context && ch == '\'')) {
    61	                        // unescape ' inside single quotes
    62	                        builder.append('\\');
    63	                    }
    64	                }
    65	            } else if (ch == '\'') {
    66	                // Turn ' into ", for proper JSON string
    67	                ch = '"';
    68	                single_context = ! single_context;
    69	            }
    70	            builder.append(ch);
    71	        }
    72	
    73	        JsonReader reader = new JsonReaderImpl(
    74	                new StringReader(builder.toString()),
    75	                new JsonContext(Collections.emptyMap(), new BufferPoolImpl()));
    76	        JsonValue value = reader.readValue();
    77	        reader.close();
    78	        return value;
    79	    }
